"declare namespace NodeJS {
  interface ProcessEnv {
    readonly EXPO_PUBLIC_API_URL?: string;
    readonly [key: string]: string | undefined;
  }
}
"

"import Constants from 'expo-constants';

/**
 * Resolves the API base URL from environment variables or expo config.
 * Priority:
 * 1. process.env.EXPO_PUBLIC_API_URL
 * 2. Constants.expoConfig?.extra?.apiUrl
 * 3. Fallback URL
 */
const resolvedApiUrl =
  process.env.EXPO_PUBLIC_API_URL ||
  (Constants.expoConfig?.extra?.apiUrl as string | undefined) ||
  'https://api.example.com';

export const API_CONFIG = {
  baseURL: resolvedApiUrl,
  timeout: 15000,
  headers: {
    'Content-Type': 'application/json',
    Accept: 'application/json',
  },
} as const;

export const API_BASE_URL = API_CONFIG.baseURL;
"

"import type { AxiosRequestConfig, AxiosResponse } from 'axios';

export interface ApiResponse<T = unknown> {
  data: T;
  message?: string;
  success?: boolean;
}

export interface ApiErrorPayload {
  message: string;
  statusCode?: number;
  errors?: Record<string, string[] | string>;
  raw?: unknown;
}

export class ApiError extends Error {
  statusCode?: number;
  errors?: Record<string, string[] | string>;
  raw?: unknown;

  constructor(payload: ApiErrorPayload) {
    super(payload.message);
    this.name = 'ApiError';
    this.statusCode = payload.statusCode;
    this.errors = payload.errors;
    this.raw = payload.raw;
  }
}

export type RequestConfig = AxiosRequestConfig;
export type ResponseData<T> = AxiosResponse<T>['data'];
"

"import axios, { type AxiosError, type AxiosInstance, type InternalAxiosRequestConfig } from 'axios';

import { API_CONFIG } from './config';
import { ApiError } from './types';

export const apiClient: AxiosInstance = axios.create({
  baseURL: API_CONFIG.baseURL,
  timeout: API_CONFIG.timeout,
  headers: API_CONFIG.headers,
});

// Request interceptor (for auth tokens, headers, logging)
apiClient.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    // Auth tokens or custom headers can be injected here
    return config;
  },
  (error: unknown) => {
    return Promise.reject(error);
  }
);

// Response interceptor (standardized error normalization)
apiClient.interceptors.response.use(
  (response) => response,
  (error: AxiosError<{ message?: string; errors?: Record<string, string[] | string> }>) => {
    const statusCode = error.response?.status;
    const responseData = error.response?.data;
    const message =
      responseData?.message ||
      error.message ||
      'An unexpected network error occurred';

    const normalizedError = new ApiError({
      message,
      statusCode,
      errors: responseData?.errors,
      raw: error,
    });

    return Promise.reject(normalizedError);
  }
);
"

"import type { AxiosRequestConfig } from 'axios';

import { apiClient } from '../client';

/**
 * Perform a GET request via Axios
 */
export async function get<TResponse>(
  url: string,
  config?: AxiosRequestConfig
): Promise<TResponse> {
  const response = await apiClient.get<TResponse>(url, config);
  return response.data;
}

/**
 * Perform a POST request via Axios
 */
export async function post<TResponse = unknown, TBody = unknown>(
  url: string,
  data?: TBody,
  config?: AxiosRequestConfig
): Promise<TResponse> {
  const response = await apiClient.post<TResponse>(url, data, config);
  return response.data;
}

/**
 * Perform a PUT request via Axios
 */
export async function put<TResponse = unknown, TBody = unknown>(
  url: string,
  data?: TBody,
  config?: AxiosRequestConfig
): Promise<TResponse> {
  const response = await apiClient.put<TResponse>(url, data, config);
  return response.data;
}

/**
 * Perform a PATCH request via Axios
 */
export async function patch<TResponse = unknown, TBody = unknown>(
  url: string,
  data?: TBody,
  config?: AxiosRequestConfig
): Promise<TResponse> {
  const response = await apiClient.patch<TResponse>(url, data, config);
  return response.data;
}

/**
 * Perform a DELETE request via Axios
 */
export async function del<TResponse = unknown>(
  url: string,
  config?: AxiosRequestConfig
): Promise<TResponse> {
  const response = await apiClient.delete<TResponse>(url, config);
  return response.data;
}
"

"import { QueryClient } from '@tanstack/react-query';

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5, // 5 minutes
      gcTime: 1000 * 60 * 30, // 30 minutes (formerly cacheTime)
      retry: 2,
      refetchOnWindowFocus: false, // Recommended for React Native
      refetchOnReconnect: true,
    },
    mutations: {
      retry: 1,
    },
  },
});
"

"import { QueryClientProvider } from '@tanstack/react-query';
import { type PropsWithChildren } from 'react';

import { queryClient as defaultQueryClient } from './query-client';

export type QueryProviderProps = PropsWithChildren<{
  client?: typeof defaultQueryClient;
}>;

export function QueryProvider({ children, client = defaultQueryClient }: QueryProviderProps) {
  return <QueryClientProvider client={client}>{children}</QueryClientProvider>;
}
"

"import {
  useQuery,
  type DefinedInitialDataOptions,
  type UndefinedInitialDataOptions,
  type UseQueryOptions,
  type UseQueryResult,
} from '@tanstack/react-query';

import type { ApiError } from '../types';

/**
 * Standardized typed wrapper for TanStack useQuery
 */
export function useApiQuery<
  TQueryFnData = unknown,
  TError = ApiError,
  TData = TQueryFnData,
>(
  options:
    | UndefinedInitialDataOptions<TQueryFnData, TError, TData>
    | DefinedInitialDataOptions<TQueryFnData, TError, TData>
    | UseQueryOptions<TQueryFnData, TError, TData>
): UseQueryResult<TData, TError> {
  return useQuery(options as UseQueryOptions<TQueryFnData, TError, TData>);
}
"

"import {
  useMutation,
  type UseMutationOptions,
  type UseMutationResult,
} from '@tanstack/react-query';

import type { ApiError } from '../types';

/**
 * Standardized typed wrapper for TanStack useMutation
 */
export function useApiMutation<
  TData = unknown,
  TVariables = void,
  TError = ApiError,
  TContext = unknown,
>(
  options: UseMutationOptions<TData, TError, TVariables, TContext>
): UseMutationResult<TData, TError, TVariables, TContext> {
  return useMutation(options);
}
"

"export * from './query-keys';
export * from './use-api-query';
export * from './use-api-mutation';
export {
  useQuery,
  useMutation,
  useQueryClient,
  useInfiniteQuery,
} from '@tanstack/react-query';
"

"export * from './config';
export * from './types';
export * from './client';
export * from './query-client';
export * from './QueryProvider';
export * from './requests';
export * from './hooks';
"

