"const TOKEN_KEY = 'cashmine_auth_token';

let inMemoryToken: string | null = null;

type TokenListener = (token: string | null) => void;
type UnauthorizedListener = () => void;

const tokenListeners = new Set<TokenListener>();
const unauthorizedListeners = new Set<UnauthorizedListener>();

function emitTokenChange(token: string | null) {
  tokenListeners.forEach((listener) => listener(token));
}

export const tokenStorage = {
  getToken: (): string | null => {
    if (typeof window !== 'undefined' && window.localStorage) {
      try {
        const stored = window.localStorage.getItem(TOKEN_KEY);
        if (stored !== null) {
          inMemoryToken = stored;
          return stored;
        }
      } catch {
        return inMemoryToken;
      }
    }
    return inMemoryToken;
  },
  setToken: (token: string): void => {
    const trimmed = token.trim();
    inMemoryToken = trimmed;
    if (typeof window !== 'undefined' && window.localStorage) {
      try {
        window.localStorage.setItem(TOKEN_KEY, trimmed);
      } catch {
      }
    }
    emitTokenChange(trimmed);
  },
  removeToken: (): void => {
    inMemoryToken = null;
    if (typeof window !== 'undefined' && window.localStorage) {
      try {
        window.localStorage.removeItem(TOKEN_KEY);
      } catch {
      }
    }
    emitTokenChange(null);
  },
};

export function notifyUnauthorized(): void {
  unauthorizedListeners.forEach((listener) => listener());
}

export function subscribeToUnauthorized(listener: UnauthorizedListener): () => void {
  unauthorizedListeners.add(listener);
  return () => {
    unauthorizedListeners.delete(listener);
  };
}

export function subscribeToToken(listener: TokenListener): () => void {
  tokenListeners.add(listener);
  return () => {
    tokenListeners.delete(listener);
  };
}
"

"import axios, { type AxiosError, type AxiosInstance, type InternalAxiosRequestConfig } from 'axios';

import { API_CONFIG } from './config';
import { tokenStorage, notifyUnauthorized } from './token';
import { ApiError, type ApiErrorResponse } from './types';

export const apiClient: AxiosInstance = axios.create({
  baseURL: API_CONFIG.baseURL,
});

apiClient.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    const url = config.url || '';
    const isV1 = url.startsWith('/v1') || url.startsWith('v1') || url.includes('/v1');
    if (isV1) {
      const token = tokenStorage.getToken();
      if (token) {
        config.headers.set('Authorization', `Bearer ${token}`);
      }
    }
    return config;
  },
  (error: unknown) => {
    return Promise.reject(error);
  }
);

apiClient.interceptors.response.use(
  (response) => response,
  (error: AxiosError<ApiErrorResponse>) => {
    const statusCode = error.response?.status;
    const errorData = error.response?.data?.error;
    const message =
      errorData?.message ||
      error.message ||
      'An unexpected network error occurred';

    if (statusCode === 401) {
      tokenStorage.removeToken();
      notifyUnauthorized();
    }

    const normalizedError = new ApiError({
      message,
      code: errorData?.code,
      field: errorData?.field,
      statusCode,
      raw: error,
    });

    return Promise.reject(normalizedError);
  }
);
"

