export type FreshnessIndicatorProps = {
  asOf?: string;
  isFetching?: boolean;
  onRefresh: () => void;
};

export function FreshnessIndicator({ asOf, isFetching, onRefresh }: FreshnessIndicatorProps) {
  const theme = useTheme();
  const [secondsAgo, setSecondsAgo] = useState(0);

  useEffect(() => {
    if (!asOf) return;
    const calculate = () => {
      const diff = Math.max(0, Math.floor((Date.now() - new Date(asOf).getTime()) / 1000));
      setSecondsAgo(diff);
    };
    calculate();
    const interval = setInterval(calculate, 1000);
    return () => clearInterval(interval);
  }, [asOf]);

  const timeLabel = !asOf
    ? 'Checking status...'
    : isFetching
      ? 'Updating snapshot...'
      : secondsAgo < 3
        ? 'Updated just now'
        : `Updated ${secondsAgo}s ago (15s cycle)`;

  return (
    <ThemedView type="backgroundElement" style={styles.container}>
      <View style={styles.leftGroup}>
        <View style={styles.statusDot} />
        <ThemedText type="small" themeColor="textSecondary">
          {timeLabel}
        </ThemedText>
      </View>

      <Pressable
        onPress={onRefresh}
        disabled={isFetching}
        style={({ pressed }) => [styles.refreshButton, pressed && styles.pressed]}>
